using static StrataLint.Scribe.DefinitionDsl;
namespace StrataLint.Scribe.Blueprint.D5.S3.Combinatorics.Circle.FourNegative.BalancedGaps;
internal sealed class SourceDocument : IScribeDocumentDefinition
{
 public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
  "Actual source masses and negative drops", H("Complete balanced four-gap chamber"),
  Blocks(Paragraph(Text("The accepted PacketNormalForm source identities supply the centered physical chains, their signs and both exact totals. The geometric sum over each actual positive interval gives its doubled mass. Erasing or inserting the chain start changes the mass by exactly its old or new base. The doubled negative increment equals its successor minus its modulus; in the enlarged fourth chain the successor is the ear value A. These are identities of the actual centered source, with no source table or prefix hypothesis added to the public theorem."))), []));
}
